style.css:
:root {
  --g-colorSchemeName: PinkMode;
  --color-background-default: #fff0f5;
  --color-background-light: #ffe4ec;
  --color-background-dark: #ffccda;
  --color-background-primary-base: #ffb6c1;
  --color-background-primary-strong: #ff69b4;
  --color-background-primary-weak: #ffc0cb;
  --color-background-secondary-base: #ffe4ec;
  --color-background-secondary-strong: #ffb6c1;
  --color-background-secondary-weak: #ffe4ec;
  --color-text-default: #ff69b4;
  --color-text-subtle: #ffb6c1;
  --color-text-inverse: #ffffff;
  --color-text-link: #ff69b4;
  --color-text-dark: #c71585;
  --color-icon-default: #ff69b4;
  --color-icon-subtle: #ffc0cb;
  --color-icon-inverse: #ffffff;
  --color-border-default: #ffc0cb;
  --color-border-strong: #ff69b4;
  --color-border-subtle: #ffe4ec;
  --color-background-button-primary-default: #ff69b4;
  --color-background-button-primary-hover: #ff1493;
  --color-background-button-primary-active: #db007d;
  --color-background-button-secondary-default: #ffe4ec;
  --color-background-button-secondary-hover: #ffc0cb;
  --color-background-button-secondary-active: #ffb6c1;
  --color-background-badge-lightwash: #ffe4ec;
  --color-background-badge-darkwash: #ffb6c1;
}
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  background: transparent;
  z-index: 9999;
  background-image: radial-gradient(white 1px, transparent 1px),
                    radial-gradient(white 1px, transparent 1px),
                    radial-gradient(white 1px, transparent 1px),
                    radial-gradient(white 1px, transparent 1px);
  background-size: 200px 200px;
  animation: twinkle 4s linear infinite;
}

@keyframes twinkle {
  0%, 100% {
    background-position: 0 0, 50px 50px, 100px 100px, 150px 150px;
  }
  50% {
    background-position: 20px 20px, 70px 70px, 120px 120px, 170px 170px;
  }
}
